{
    struct sk_buff *skb;
    int ret = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_mutex);
        return -EBUSY;
    }

    if (!sk->sk_rcvbuf || sk->sk_rcvbuf < NLMSG_HDRLEN) {
        ret = -ENOBUFS;
        goto out;
    }

    skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
    if (!skb) {
        ret = -ENOMEM;
        goto out;
    }

    if (!sk->sk_data) {
        ret = -EINVAL;
        kfree_skb(skb);
        goto out;
    }

    ret = sk->sk_data(skb);
    if (ret < 0) {
        kfree_skb(skb);
        goto out;
    }

    if (sk->sk_filter) {
        ret = sk_filter(skb);
        if (ret < 0) {
            kfree_skb(skb);
            goto out;
        }
        send_skb(skb);
    } else {
        send_skb(skb);
    }

    ret = 0;

out:
    mutex_unlock(&sk->sk_mutex);
    return ret;
}

