int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb;
    int ret = 0;

    mutex_lock(&sk->sk_lock);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_lock);
        return -EBUSY;
    }

    if (!sk->sk_rmem_alloc)
        goto out_unlock;

    skb = alloc_skb(NLMSG_SPACE(1024), GFP_KERNEL);
    if (!skb) {
        ret = -ENOMEM;
        goto out_unlock;
    }

    sk->sk_callback_running = 1;
    ret = sk->sk_data_ready(sk, skb);
    sk->sk_callback_running = 0;

    if (ret < 0) {
        kfree_skb(skb);
        goto out_unlock;
    }

    if (sk->sk_filter) {
        skb_push(skb, skb->data - skb->head);
        sk_filter(skb, sk->sk_filter);
        skb_set_transport_header(skb, skb_headroom(skb));
    }

    if (skb_queue_empty(&sk->sk_receive_queue)) {
        skb_queue_tail(&sk->sk_receive_queue, skb);
    } else {
        kfree_skb(skb);
    }

out_unlock:
    mutex_unlock(&sk->sk_lock);
    return ret;
}

