    }

    skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
    if (!skb) {
        err = -ENOMEM;
        goto out;
    }

    if (!sk->sk_data_ready(sk, skb)) {
        err = -EFAULT;
        kfree_skb(skb);
        goto out;
    }

    if (sk->dump_callback) {
        err = sk->dump_callback(sk, skb);
        if (err < 0) {
            kfree_skb(skb);
            goto out;
        }
    }

    if (sk->filter) {
        err = sk->filter(sk, skb);
        if (err < 0) {
            kfree_skb(skb);
            goto out;
        }
    } else {
        netlink_unicast(sk, skb, sk->sk_pid);
    }

out:
    mutex_unlock(&sk->sk_mutex);
    return err;
}

